    /// <summary>
    /// Whether <paramref name="key"/> contains one of <see cref="DeniedKeyTokens"/> (ordinal, case-insensitive).
    /// </summary>
    public static bool ContainsDeniedToken(string key)
    {
        if (key is null) throw new global::System.ArgumentNullException(nameof(key));
        foreach (var token in DeniedKeyTokens)
        {
            if (key.IndexOf(token, global::System.StringComparison.OrdinalIgnoreCase) >= 0) return true;
        }
        return false;
    }

    /// <summary>
    /// Whether the qyl collector persists <paramref name="key"/> as an attribute.
    /// </summary>
    public static bool IsPersisted(string key)
    {
        if (key is null) throw new global::System.ArgumentNullException(nameof(key));
        return IsPersistedName(key);
    }

    private static bool IsPersistedName(string key)
    {
        foreach (var denied in NotPersistedKeys)
        {
            if (string.Equals(key, denied, global::System.StringComparison.Ordinal)) return false;
            if (key.Length > denied.Length && key[denied.Length] == '.' && key.StartsWith(denied, global::System.StringComparison.Ordinal)) return false;
        }
        foreach (var prefix in NotPersistedPrefixes)
        {
            if (key.StartsWith(prefix, global::System.StringComparison.OrdinalIgnoreCase)) return false;
        }
        foreach (var exact in ExceptionTextKeys)
        {
            if (string.Equals(key, exact, global::System.StringComparison.Ordinal)) continue;
            if (string.Equals(key, exact, global::System.StringComparison.OrdinalIgnoreCase) ||
                key.Length > exact.Length && key[exact.Length] == '.' && key.StartsWith(exact, global::System.StringComparison.OrdinalIgnoreCase)) return false;
        }
        if (TryGetCapturedFieldPersistence(key, out var captured)) return captured;
        foreach (var exempt in TokenExemptKeys)
        {
            if (string.Equals(key, exempt, global::System.StringComparison.Ordinal)) return true;
        }
        foreach (var vendor in VendorKeys)
        {
            if (string.Equals(key, vendor, global::System.StringComparison.Ordinal)) return true;
        }
        return !ContainsDeniedToken(key);
    }
